import sys, json
from typing import List

class Solution:
    def minDistance(self, houses: List[int], k: int) -> int:
        houses.sort()
        n = len(houses)

        prefix = [0] * (n + 1)
        for i, x in enumerate(houses):
            prefix[i + 1] = prefix[i] + x

        def cost(left: int, right: int) -> int:
            mid = (left + right) // 2
            left_cost = houses[mid] * (mid - left + 1) - (prefix[mid + 1] - prefix[left])
            right_cost = (prefix[right + 1] - prefix[mid + 1]) - houses[mid] * (right - mid)
            return left_cost + right_cost

        INF = 10**18

        dp = [INF] * n
        for right in range(n):
            dp[right] = cost(0, right)

        for boxes in range(2, k + 1):
            new_dp = [INF] * n
            for right in range(boxes - 1, n):
                for split in range(boxes - 2, right):
                    if dp[split] != INF:
                        new_dp[right] = min(
                            new_dp[right],
                            dp[split] + cost(split + 1, right)
                        )
            dp = new_dp

        return dp[n - 1]

