static int cmp_int(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}


static long long cost_range(const int *houses, const long long *prefix, int left, int right) {
    int mid = (left + right) / 2;

    long long leftCost =
        (long long)houses[mid] * (mid - left + 1)
        - (prefix[mid + 1] - prefix[left]);

    long long rightCost =
        (prefix[right + 1] - prefix[mid + 1])
        - (long long)houses[mid] * (right - mid);

    return leftCost + rightCost;
}

static int minDistance(int *houses, int housesSize, int k) {
    qsort(houses, housesSize, sizeof(int), cmp_int);

    int n = housesSize;
    long long prefix[101];
    prefix[0] = 0;

    for (int i = 0; i < n; ++i) {
        prefix[i + 1] = prefix[i] + houses[i];
    }

    long long dp[101];
    long long next[101];
    const long long INF = (1LL << 60);

    /* Cost of placing one mailbox for houses[left..right] at a median. */
    #define COST(left, right) cost_range(houses, prefix, (left), (right))

    for (int right = 0; right < n; ++right) {
        dp[right] = COST(0, right);
    }

    for (int boxes = 2; boxes <= k; ++boxes) {
        for (int i = 0; i < n; ++i) next[i] = INF;

        for (int right = boxes - 1; right < n; ++right) {
            for (int split = boxes - 2; split < right; ++split) {
                long long candidate =
                    dp[split] + COST(split + 1, right);

                if (candidate < next[right]) {
                    next[right] = candidate;
                }
            }
        }

        for (int i = 0; i < n; ++i) dp[i] = next[i];
    }

    #undef COST
    return (int)dp[n - 1];
}

int main(void) {
    char line[200000];

    if (!fgets(line, sizeof(line), stdin)) {
        return 1;
