#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int minDistance(vector<int>& houses, int k) {
        sort(houses.begin(), houses.end());
        int n = (int)houses.size();

        vector<long long> prefix(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            prefix[i + 1] = prefix[i] + houses[i];
        }

        auto cost = [&](int left, int right) -> long long {
            int mid = (left + right) / 2;

            long long leftCost =
                1LL * houses[mid] * (mid - left + 1)
                - (prefix[mid + 1] - prefix[left]);

            long long rightCost =
                (prefix[right + 1] - prefix[mid + 1])
                - 1LL * houses[mid] * (right - mid);

            return leftCost + rightCost;
        };

        const long long INF = (1LL << 60);
        vector<long long> dp(n, INF);

        for (int right = 0; right < n; ++right) {
            dp[right] = cost(0, right);
        }

        for (int boxes = 2; boxes <= k; ++boxes) {
            vector<long long> next(n, INF);

            for (int right = boxes - 1; right < n; ++right) {
                for (int split = boxes - 2; split < right; ++split) {
                    next[right] = min(
                        next[right],
                        dp[split] + cost(split + 1, right)
                    );
                }
            }

            dp.swap(next);
        }

        return (int)dp[n - 1];
    }
};

static vector<int> parseHouses(const string& line) {
    size_t innerStart = line.find('[', 1);
    size_t innerEnd = line.find(']', innerStart);
    string body = line.substr(innerStart + 1, innerEnd - innerStart - 1);

    vector<int> houses;
    stringstream ss(body);
    int x;
    char comma;

    while (ss >> x) {
        houses.push_back(x);
        if (ss.peek() == ',') ss >> comma;
    }

    return houses;
}

static int parseK(const string& line) {
    size_t innerEnd = line.find(']');
    size_t comma = line.find(',', innerEnd);
    return stoi(line.substr(comma + 1, line.size() - comma - 2));
}

int main() {
    string line;
    getline(cin, line);

    vector<int> houses = parseHouses(line);
    int k = parseK(line);

    cout << Solution().minDistance(houses, k) << '\n';
    return 0;
}

