import java.io.*;
import java.util.*;

class Solution {
    public int minDistance(int[] houses, int k) {
        Arrays.sort(houses);
        int n = houses.length;

        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + houses[i];
        }

        long[] dp = new long[n];
        for (int right = 0; right < n; right++) {
            dp[right] = cost(houses, prefix, 0, right);
        }

        final long INF = Long.MAX_VALUE / 4;
        for (int boxes = 2; boxes <= k; boxes++) {
            long[] next = new long[n];
            Arrays.fill(next, INF);

            for (int right = boxes - 1; right < n; right++) {
                for (int split = boxes - 2; split < right; split++) {
                    next[right] = Math.min(
                        next[right],
                        dp[split] + cost(houses, prefix, split + 1, right)
                    );
                }
            }
            dp = next;
        }

        return (int) dp[n - 1];
    }

    private long cost(int[] houses, long[] prefix, int left, int right) {
        int mid = (left + right) / 2;

        long leftCost =
            (long) houses[mid] * (mid - left + 1)
            - (prefix[mid + 1] - prefix[left]);

        long rightCost =
            (prefix[right + 1] - prefix[mid + 1])
            - (long) houses[mid] * (right - mid);

        return leftCost + rightCost;
    }
}

public class Main {
    private static int[] parseHouses(String line) {
        int innerStart = line.indexOf('[', 1);
        int innerEnd = line.indexOf(']', innerStart);
        String body = line.substring(innerStart + 1, innerEnd).trim();
        if (body.isEmpty()) return new int[0];

        String[] parts = body.split(",");
        int[] result = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            result[i] = Integer.parseInt(parts[i].trim());
        }
        return result;
    }

    private static int parseK(String line) {
        int innerEnd = line.indexOf(']');
        int comma = line.indexOf(',', innerEnd);
        return Integer.parseInt(line.substring(comma + 1, line.length() - 1).trim());
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine().trim();

        int[] houses = parseHouses(line);
        int k = parseK(line);

        System.out.println(new Solution().minDistance(houses, k));
    }
}

