const readline = require("readline");

function minDistance(houses, k) {
    houses.sort((a, b) => a - b);
    const n = houses.length;

    const prefix = Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + houses[i];
    }

    function cost(left, right) {
        const mid = Math.floor((left + right) / 2);
        const leftCost =
            houses[mid] * (mid - left + 1) -
            (prefix[mid + 1] - prefix[left]);
        const rightCost =
            (prefix[right + 1] - prefix[mid + 1]) -
            houses[mid] * (right - mid);
        return leftCost + rightCost;
    }

    const INF = Number.POSITIVE_INFINITY;
    let dp = Array(n).fill(INF);

    for (let right = 0; right < n; right++) {
        dp[right] = cost(0, right);
    }

    for (let boxes = 2; boxes <= k; boxes++) {
        const next = Array(n).fill(INF);

        for (let right = boxes - 1; right < n; right++) {
            for (let split = boxes - 2; split < right; split++) {
                next[right] = Math.min(
                    next[right],
                    dp[split] + cost(split + 1, right)
                );
            }
        }

        dp = next;
    }

    return dp[n - 1];
}

